[dependencies]
rig = { version = "0.44.0", features = ["pdf"] }
tokio = { version = "1", features = ["full"] }
anyhow = "1"
serde = { version = "1", features = ["derive"] }

use rig::Embed;
use rig::loaders::PdfFileLoader;
use serde::Serialize;


/// One page of a PDF. `#[embed]` marks the field that gets embedded.
#[derive(Embed, Serialize, Clone)]
struct Page {
    id: String,
    #[embed]
    text: String,
}


fn load_pages(glob: &str) -> anyhow::Result<Vec<Page>> {
    let pages = PdfFileLoader::with_glob(glob)?
        .load()
        .ignore_errors() // skip files that fail to open
        .by_page()
        .into_iter()
        .collect::<Result<Vec<String>, _>>()?;


    Ok(pages
        .into_iter()
        .enumerate()
        .filter(|(_, text)| !text.trim().is_empty())
        .map(|(i, text)| Page { id: format!("page-{i}"), text })
        .collect())
}

use rig::embeddings::EmbeddingsBuilder;
use rig::providers::openai::{self, OpenAI};
use rig::vector_store::in_memory_store::InMemoryVectorStore;


let openai_client = OpenAI::from_env()?;
let embedding_model = openai_client
    .embedding(openai::TEXT_EMBEDDING_3_SMALL, None)
    .erase();


let pages = load_pages("documents/*.pdf")?;


let embeddings = EmbeddingsBuilder::new(embedding_model.clone())
    .documents(pages)?
    .build()
    .await?;


let vector_store = InMemoryVectorStore::from_documents_with_id_f(embeddings, |page| page.id.clone());

let index = vector_store.index(embedding_model);


let rag_agent = AgentBuilder::new(openai_client.completion(openai::GPT_5_5))
    .preamble("You are a helpful assistant that answers questions using the provided PDF context.")
    .dynamic_context(4, index)
    .build();

use rig::vector_store::{VectorSearchRequest, VectorStoreIndex};


let req = VectorSearchRequest::builder()
    .query("what did Sam Altman write?")
    .samples(2)
    .build();


for hit in index.top_n::<Page>(req).await? {
    println!("{:.3} {}: {}", hit.score, hit.id, hit.document.text);
}

use rig::Embed;
use rig::embeddings::EmbeddingsBuilder;
use rig::integrations::cli_chatbot::ChatBotBuilder;
use rig::loaders::PdfFileLoader;
use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};
use rig::vector_store::in_memory_store::InMemoryVectorStore;
use serde::Serialize;


#[derive(Embed, Serialize, Clone)]
struct Page {
    id: String,
    #[embed]
    text: String,
}


fn load_pages(glob: &str) -> anyhow::Result<Vec<Page>> {
    let pages = PdfFileLoader::with_glob(glob)?
        .load()
        .ignore_errors()
        .by_page()
        .into_iter()
        .collect::<Result<Vec<String>, _>>()?;


    Ok(pages
        .into_iter()
        .enumerate()
        .filter(|(_, text)| !text.trim().is_empty())
        .map(|(i, text)| Page { id: format!("page-{i}"), text })
        .collect())
}


#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let openai_client = OpenAI::from_env()?;
    let embedding_model = openai_client
        .embedding(openai::TEXT_EMBEDDING_3_SMALL, None)
        .erase();


    let embeddings = EmbeddingsBuilder::new(embedding_model.clone())
        .documents(load_pages("documents/*.pdf")?)?
        .build()
        .await?;


    let index = InMemoryVectorStore::from_documents_with_id_f(embeddings, |page| page.id.clone())
        .index(embedding_model);


    let rag_agent = AgentBuilder::new(openai_client.completion(openai::GPT_5_5))
        .preamble("You are a helpful assistant that answers questions using the provided PDF context.")
        .dynamic_context(4, index)
        .build();


    let chatbot = ChatBotBuilder::new().agent(rag_agent).build();
    chatbot.run().await?;


    Ok(())
}
